        "step_number": 2,
        "instruction": "Create a small example dataset",
        "code": "example_data <- data.frame(\n  Category = c('A', 'B', 'C', 'D'),\n  Value = c(23, 45, 12, 34)\n)"
      },
      {
        "step_number": 3,
        "instruction": "Create a basic bar chart",
        "code": "ggplot(data = example_data, aes(x = Category, y = Value)) +\n  geom_bar(stat = 'identity')"
      },
      {
        "step_number": 4,
        "instruction": "Customize the bar chart (optional)",
        "code": "ggplot(data = example_data, aes(x = Category, y = Value)) +\n  geom_bar(stat = 'identity', fill = 'steelblue') +\n  labs(title = 'Example Bar Chart', x = 'Category', y = 'Value') +\n  theme_minimal()"
      }
    ],
