      },
      {
        "time": "5-10 minutes",
        "activity": "Key Vocabulary and Overview",
        "description": "Define and explain key terms: photosynthesis, chlorophyll, chloroplasts, sunlight, carbon dioxide, water, glucose, oxygen. Show a simple diagram of the process."
      },
      {
        "time": "10-20 minutes",
        "activity": "Interactive Demo - Photosynthesis in Action",
        "description": "Set up a quick demo using a potted plant or cut leaf in a cup with water and a pinch of baking soda. Place under a light source. Observe and explain how the plant uses light, water, and CO2 to produce oxygen and glucose."
      },
      {
        "time": "20-30 minutes",
        "activity": "Group Activity - Diagram Labeling",
        "description": "Divide students into small groups and give each a handout with a diagram of the photosynthesis process. Have them label the inputs, outputs, and the role of chlorophyll. Walk around to assist and clarify."
      },
      {
        "time": "30-40 minutes",
        "activity": "Review and Discussion",
        "description": "Have each group share their diagram with the class. Discuss any questions or misconceptions. Emphasize the importance of photosynthesis to the food chain and the environment."
      },
      {
        "time": "40-45 minutes",
        "activity": "Wrap-Up and Exit Ticket",
        "description": "Ask students to write a one-sentence summary of what they learned about photosynthesis on a sticky note or paper. Collect and review for understanding."
