{
  "CAP_Theorem_Explained": {
    "Definition": "The CAP theorem, also known as Brewer's theorem, states that in a distributed system, it is impossible to simultaneously guarantee all three of the following properties: Consistency, Availability, and Partition Tolerance.",
    "Properties": {
      "Consistency": "Every read receives the most recent write or an error.",
      "Availability": "Every request receives a response, without guarantee that it contains the most recent write.",
      "Partition Tolerance": "The system continues to operate despite arbitrary partitioning due to network failures."
    },
    "Tradeoffs": {
      "CA": "Consistency and Availability, but no Partition Tolerance. Example: Traditional relational databases (e.g., MySQL in a single data center).",
      "CP": "Consistency and Partition Tolerance, but no Availability. Example: Apache HBase or MongoDB with strong consistency settings.",
      "AP": "Availability and Partition Tolerance, but no Consistency. Example: Apache Cassandra or Amazon DynamoDB in eventual consistency mode."
    },
    "Example_Scenarios": {
      "CA_System": "A local bank’s database in a single location ensures every transaction is consistent and available, but if the network goes down, the system is unavailable.",
      "CP_System": "A stock trading system ensures every trade is consistent and processes transactions even during network issues, but may reject some requests to maintain consistency.",
      "AP_System": "A social media platform ensures users can always post and view content even during network failures, but users might see outdated posts until the system converges."
    }
  }
}
