"function mergeTwoLists(l1, l2) {
    // Create a dummy node to act as the starting point of the merged list
    let dummy = new ListNode();
    // 'tail' will be used to build the merged list by appending nodes
    let tail = dummy;

    // Traverse both lists until one of them is fully processed
    while (l1 !== null && l2 !== null) {
        if (l1.val < l2.val) {
            tail.next = l1;
            l1 = l1.next;
        } else {
            tail.next = l2;
            l2 = l2.next;
        }
        tail = tail.next;
    }

    // If there are remaining elements in l1 or l2, append them
    tail.next = l1 !== null ? l1 : l2;

    // The merged list is next to the dummy node
    return dummy.next;
}

// Definition for singly-linked list node
class ListNode {
    constructor(val = 0, next = null) {
        this.val = val;
        this.next = next;
    }
}"

