}"

"package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
)

// Function to read a JSON file and print top-level keys
func printTopLevelKeys(filename string) {
	// Open the JSON file
	file, err := os.Open(filename)
	if err != nil {
		fmt.Println(\"Error opening file:\", err)
		return
	}
	defer file.Close()

	// Read the JSON data
	data, err := ioutil.ReadAll(file)
	if err != nil {
		fmt.Println(\"Error reading file:\", err)
		return
	}

	// Parse the JSON data
	var result map[string]interface{}
	err = json.Unmarshal(data, &result)
	if err != nil {
		fmt.Println(\"Error parsing JSON:\", err)
		return
	}

	// Print the top-level keys
	fmt.Println(\"Top-level keys:\")
	for key := range result {
		fmt.Println(\"-\", key)
	}
}

func main() {
	// Example usage: provide the JSON file path
	filename := \"data.json\"
	printTopLevelKeys(filename)
}"
